281			if got := statusUsageTotal(t, st, feb(2026)); got != w.febTotal {
282				t.Fatalf("account %q status feb usage = %d, want %d", w.acct, got, w.febTotal)
283			}
284			if len(st.Bills) != 1 {
285				t.Fatalf("account %q status bills = %+v", w.acct, st.Bills)
286			}
287			bs := statusBillSummary(t, st, jan(2026))
288			if bs.TotalDue != 1000 || bs.Balance != w.janBalance || bs.Settled != w.janSettled {
289				t.Fatalf("account %q status jan bill = %+v", w.acct, bs)
290			}
291			if !bs.DueAt.Equal(crossAcctDueAt) {
292				t.Fatalf("account %q jan due at = %v, want %v", w.acct, bs.DueAt, crossAcctDueAt)
293			}
294		}
295	
296		// 时钟没有被任何操作推动：截止时刻语义始终按注入时钟裁决。
297		if !clk.t.Equal(crossAcctDueAt) {
298			t.Fatalf("clock moved unexpectedly: %v", clk.t)
299		}
300		// 二月始终未出账；两账户一月账单保持各自的付款结果。
301		for _, acct := range []string{crossAcctJia, crossAcctYi} {
302			if _, err := s.GetBill(acct, feb(2026)); !errors.Is(err, ErrBillNotFound) {
303				t.Fatalf("account %q feb bill should still not exist: %v", acct, err)
304			}
305		}
306		wantCrossAccountJanBill(t, s, crossAcctJia, 1000, 0, true)
307		wantCrossAccountJanBill(t, s, crossAcctYi, 1000, 0, true)
308		wantCrossAccountFlags(t, s, false, false)
309	}
310	
311	// TestSuspendedAndActiveAccountsSharedEventID 覆盖完整场景，并通过两种提交
312	// 顺序保证结果与“先提交哪个账户”无关。
313	func TestSuspendedAndActiveAccountsSharedEventID(t *testing.T) {
314		t.Run("jia rejected first", func(t *testing.T) { runCrossAccountScenario(t, true) })
315		t.Run("yi accepted first", func(t *testing.T) { runCrossAccountScenario(t, false) })
316	}
317	
318	// TestSharedEventIDAcrossSuspendedAccountsConcurrent 并发版本：甲停用、乙正常
319	// 时两者在同一瞬间用同一标识首次上报。每个账户的“去重判定 → 校验 → 落库”
320	// 都在各自账户的临界区裁决，甲必须 ErrSuspended 且不留记录，乙必须首次
321	// 接收成功；不能因为并发碰撞把任一方判成跨账户冲突或重报。
322	func TestSharedEventIDAcrossSuspendedAccountsConcurrent(t *testing.T) {
323		const rounds = 50
324		for iter := 0; iter < rounds; iter++ {
325			s, _ := suspendedCrossAccountFixture(t)
326	
327			type outcome struct {
328				r   EventResult
329				err error
330			}
331			resJia := make(chan outcome, 1)
332			resYi := make(chan outcome, 1)
333			start := make(chan struct{})
334			go func() {
335				<-start
336				r, err := s.RecordEvent(crossAcctJiaEvent())
337				resJia <- outcome{r, err}
338			}()
339			go func() {
340				<-start
341				r, err := s.RecordEvent(crossAcctYiEvent())
342				resYi <- outcome{r, err}
343			}()
344			close(start)
345			oj := <-resJia
346			oy := <-resYi
347	
348			if !errors.Is(oj.err, ErrSuspended) {
349				t.Fatalf("iter %d concurrent jia: r=%+v err=%v, want ErrSuspended", iter, oj.r, oj.err)
350			}
351			if oy.err != nil || !oy.r.Accepted || oy.r.Period != feb(2026) {
352				t.Fatalf("iter %d concurrent yi: r=%+v err=%v, want first accepted into 2026-02", iter, oy.r, oy.err)
353			}
354			wantCrossAccountFebUsage(t, s, 0, 7)
355			wantCrossAccountFlags(t, s, true, false)
356		}
357	}
358	
359	// TestSharedEventIDAcceptedConcurrentlyAfterPayment 并发版本的恢复段：甲先
360	// 结清一月账单解除停用，随后两者并发地用同一标识首次上报（数量不同）。
361	// 两笔都必须在各自账户内作为首次上报接收，互不冲突、互不累计到对方。
362	func TestSharedEventIDAcceptedConcurrentlyAfterPayment(t *testing.T) {
363		const rounds = 50
364		for iter := 0; iter < rounds; iter++ {
365			s, _ := suspendedCrossAccountFixture(t)
366			if r, err := s.RecordPayment(crossAcctJia, "pay-jia-jan", jan(2026), 1000); err != nil ||
367				!r.Registered || r.BillBalance != 0 || !r.Settled {
368				t.Fatalf("iter %d jia payment: r=%+v err=%v", iter, r, err)
369			}
370			wantCrossAccountFlags(t, s, false, false)
371	
372			type outcome struct {
373				r   EventResult
374				err error
375			}
376			resJia := make(chan outcome, 1)
377			resYi := make(chan outcome, 1)
378			start := make(chan struct{})
379			go func() {
380				<-start
381				r, err := s.RecordEvent(crossAcctJiaEvent())
382				resJia <- outcome{r, err}
383			}()
384			go func() {
385				<-start
386				r, err := s.RecordEvent(crossAcctYiEvent())
387				resYi <- outcome{r, err}
388			}()
389			close(start)
390			oj := <-resJia
391			oy := <-resYi
392	
393			if oj.err != nil || !oj.r.Accepted || oj.r.Period != feb(2026) {
394				t.Fatalf("iter %d concurrent jia after payment: r=%+v err=%v", iter, oj.r, oj.err)
395			}
396			if oy.err != nil || !oy.r.Accepted || oy.r.Period != feb(2026) {
397				t.Fatalf("iter %d concurrent yi after jia payment: r=%+v err=%v", iter, oy.r, oy.err)
398			}
399			wantCrossAccountFebUsage(t, s, 3, 7)
400			wantCrossAccountJanBill(t, s, crossAcctJia, 1000, 0, true)
401			wantCrossAccountJanBill(t, s, crossAcctYi, 1000, 0, true)
402			wantCrossAccountFlags(t, s, false, false)
403	
404			// 再并发原样重报：两者都只命中各自的接收记录，Accepted=false，不累计。
405			rj2 := make(chan outcome, 1)
406			ry2 := make(chan outcome, 1)
407			start2 := make(chan struct{})
408			go func() {
409				<-start2
410				r, err := s.RecordEvent(crossAcctJiaEvent())
411				rj2 <- outcome{r, err}
412			}()
413			go func() {
414				<-start2
415				r, err := s.RecordEvent(crossAcctYiEvent())
416				ry2 <- outcome{r, err}
417			}()
418			close(start2)
419			oj2 := <-rj2
420			oy2 := <-ry2
421			if oj2.err != nil || oj2.r.Accepted || oj2.r.Period != feb(2026) {
422				t.Fatalf("iter %d concurrent jia replay: r=%+v err=%v", iter, oj2.r, oj2.err)
423			}
424			if oy2.err != nil || oy2.r.Accepted || oy2.r.Period != feb(2026) {
425				t.Fatalf("iter %d concurrent yi replay: r=%+v err=%v", iter, oy2.r, oy2.err)
426			}
427			wantCrossAccountFebUsage(t, s, 3, 7)
428		}
429	}
