2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8	)
9	
10	// 本文件回归“两笔不同付款标识争用同一张账单的同一笔余额”。
11	//
12	// 已有保障覆盖了顺序分次付款，以及同一付款标识并发重报只扣款一次；这里补充的是
13	// 标识不同、各自单独看都合法的两笔付款并发到达的情况。付款能否登记必须以登记
14	// 那一刻账单的实际剩余应付为准：实现把“去重判定 → 账单查找 → 余额校验 → 扣款
15	// 落库 → 付款标识落库”全部放在同一把互斥锁的一个临界区内，因此两笔请求必然
16	// 串行裁决，后到的一笔看到的是先到一笔扣款后的真实余额。
17	//
18	// 这些测试锁住该行为，防止日后把余额检查与扣款拆成两个步骤（TOCTOU）而出现：
19	// 两笔都登记成功、已付金额超出应付、负余额、误报付清，或失败的一笔占用了付款
20	// 标识。
21	
22	// paymentOutcome 记录一笔并发付款的标识、金额与返回结果。
23	type paymentOutcome struct {
24		id     string
25		amount int64
26		r      PaymentResult
27		err    error
28	}
29	
30	// mustBill1000 在指定账户上出一张 2026-01 的账单：应付与余额均为 1000 分、
31	// 已付 0、未付清、税额 0、用量 0，且尚未收到任何付款。
32	func mustBill1000(t *testing.T, s *Service, acct string) {
33		t.Helper()
34		mustAccount(t, s, acct)
35		if err := s.Subscribe(acct, "plan1000", utc(2026, 1, 1, 0, 0)); err != nil {
36			t.Fatalf("subscribe %q: %v", acct, err)
37		}
38		b, err := s.CreateBill(acct, jan(2026))
39		if err != nil {
40			t.Fatalf("create bill %q: %v", acct, err)
41		}
42		if b.TotalDue != 1000 || b.Paid != 0 || b.Balance != 1000 || b.Settled || b.Tax != 0 || b.TotalUsage != 0 {
43			t.Fatalf("bill %q initial state: %+v", acct, b)
44		}
45	}
46	
47	// contendOnce 用启动屏障让两笔不同标识的付款在同一时刻争用同一张账单，
48	// 返回与传入顺序一致的两笔结果。屏障保证两笔真正并发，而非顺序提交。
49	func contendOnce(s *Service, acct string, first paymentOutcome, second paymentOutcome) []paymentOutcome {
50		reqs := []paymentOutcome{first, second}
51		res := make([]paymentOutcome, 2)
52		start := make(chan struct{})
53		var wg sync.WaitGroup
54		wg.Add(2)
55		for i, q := range reqs {
56			go func(i int, q paymentOutcome) {
57				defer wg.Done()
58				<-start
59				r, err := s.RecordPayment(acct, q.id, jan(2026), q.amount)
60				res[i] = paymentOutcome{id: q.id, amount: q.amount, r: r, err: err}
61			}(i, q)
62		}
63		close(start)
64		wg.Wait()
65		return res
66	}
67	
68	// billSummary1000 返回账户状态中 2026-01 账单的摘要，测试断言其与账单查询一致。
69	func billSummary1000(t *testing.T, s *Service, acct string) BillSummary {
70		t.Helper()
71		st, err := s.Status(acct)
72		if err != nil {
73			t.Fatalf("status %q: %v", acct, err)
74		}
75		for _, bs := range st.Bills {
76			if bs.Period == jan(2026) {
77				return bs
78			}
79		}
80		t.Fatalf("status %q has no Jan bill: %+v", acct, st.Bills)
81		return BillSummary{}
82	}
83	
84	// TestConcurrentDistinctPaymentsOnlyOneWithinBalance 覆盖第一张例子：
85	// 初始余额 1000，两笔标识不同的付款 700 与 400 并发到达。它们单独提交都合法，
86	// 但不能一起登记成功：恰好一笔首次登记成功，另一笔返回 ErrPaymentExceedsBalance。
87	// 允许任意一笔先成功，两种结果都未付清。
88	func TestConcurrentDistinctPaymentsOnlyOneWithinBalance(t *testing.T) {
89		s, _ := newTestService(utc(2026, 2, 1, 0, 0))
90		mustPlan(t, s, Plan{ID: "plan1000", MonthlyFee: 1000, TaxRateBasisPoints: 0})
91	
92		const rounds = 100
93		for iter := 0; iter < rounds; iter++ {
94			acct := fmt.Sprintf("a%d", iter)
95			mustBill1000(t, s, acct)
96	
97			res := contendOnce(s, acct,
98				paymentOutcome{id: "p700", amount: 700},
99				paymentOutcome{id: "p400", amount: 400},
100			)
101	
102			// 恰好一笔首次登记成功，恰好一笔因超额被拒；不允许两笔都成功，
103			// 也不允许返回标识冲突等其它错误。
104			var winner paymentOutcome
105			var loser *paymentOutcome
106			nRegistered, nExceeded := 0, 0
107			for i := range res {
108				oc := &res[i]
109				switch {
110				case oc.err == nil && oc.r.Registered:
111					nRegistered++
112					winner = *oc
113				case errors.Is(oc.err, ErrPaymentExceedsBalance):
114					nExceeded++
115					loser = oc
116				default:
117					t.Fatalf("iter %d payment %q unexpected: r=%+v err=%v", iter, oc.id, oc.r, oc.err)
118				}
119			}
120			if nRegistered != 1 || nExceeded != 1 || loser == nil {
121				t.Fatalf("iter %d want exactly one registered and one exceeds-balance, got %+v", iter, res)
122			}
123	
124			// 按实际先成功者确定账单剩余余额；两种结果都未付清。
125			var remaining int64
126			switch winner.id {
127			case "p700":
128				remaining = 300 // 已付 700、余额 300。
129			case "p400":
130				remaining = 600 // 已付 400、余额 600。
131			default:
132				t.Fatalf("iter %d unknown winner %q", iter, winner.id)
133			}
134			if winner.r.BillBalance != remaining || winner.r.Settled {
135				t.Fatalf("iter %d winner %q result: %+v, want balance=%d settled=false",
136					iter, winner.id, winner.r, remaining)
137			}
138	
139			// 失败的一笔不得部分计入已付，也不得产生负余额或误报付清。
140			b, err := s.GetBill(acct, jan(2026))
141			if err != nil {
142				t.Fatalf("iter %d get bill: %v", iter, err)
143			}
144			if b.Paid != winner.amount || b.Balance != remaining || b.Settled || b.Balance < 0 {
145				t.Fatalf("iter %d bill after contention: paid=%d balance=%d settled=%v, want paid=%d balance=%d",
146					iter, b.Paid, b.Balance, b.Settled, winner.amount, remaining)
147			}
148			// 应付、税额与用量明细保持不变。
149			if b.TotalDue != 1000 || b.Tax != 0 || b.TotalUsage != 0 ||
150				b.MonthlyFee != 1000 || b.OverageFee != 0 {
151				t.Fatalf("iter %d bill immutable fields changed: %+v", iter, b)
152			}
153			// 账户状态中的账单摘要必须反映同一种实际结果。
154			if bs := billSummary1000(t, s, acct); bs.TotalDue != 1000 ||
155				bs.Paid != winner.amount || bs.Balance != remaining || bs.Settled {
156				t.Fatalf("iter %d status summary diverges: %+v", iter, bs)
157			}
158	
159			// 被拒绝的那笔不占用付款标识：用它原来的标识、把金额改为此时的剩余余额，
160			// 应能作为首次成功付款登记并结清，而不是报标识冲突。
161			topUp, err := s.RecordPayment(acct, loser.id, jan(2026), remaining)
162			if errors.Is(err, ErrPaymentConflict) {
163				t.Fatalf("iter %d rejected payment id %q was consumed: %v", iter, loser.id, err)
164			}
165			if err != nil || !topUp.Registered || topUp.Payment.PaymentID != loser.id ||
166				topUp.Payment.Amount != remaining || topUp.BillBalance != 0 || !topUp.Settled {
167				t.Fatalf("iter %d reuse rejected id %q for remaining %d: r=%+v err=%v",
168					iter, loser.id, remaining, topUp, err)
169			}
170	
171			// 此后原样重报最先成功的那笔：仍按已有规则返回它首次登记后的余额与未付清
172			// 状态（历史结果），Registered 为 false，不再次增加已付金额。
173			replay, err := s.RecordPayment(acct, winner.id, jan(2026), winner.amount)
174			if err != nil || replay.Registered ||
175				replay.BillBalance != remaining || replay.Settled {
176				t.Fatalf("iter %d replay winner %q: r=%+v err=%v, want historical balance=%d settled=false",
177					iter, winner.id, replay, err, remaining)
178			}
179	
180			// 账单查询与账户状态显示当前实际状态：已付 1000、余额 0、已付清，
181			// 不被旧付款返回的历史结果覆盖。
182			b, _ = s.GetBill(acct, jan(2026))
183			if b.Paid != 1000 || b.Balance != 0 || !b.Settled {
184				t.Fatalf("iter %d final bill: paid=%d balance=%d settled=%v, want 1000/0/true",
185					iter, b.Paid, b.Balance, b.Settled)
186			}
187			if bs := billSummary1000(t, s, acct); bs.Paid != 1000 || bs.Balance != 0 || !bs.Settled {
188				t.Fatalf("iter %d final status summary: %+v", iter, bs)
189			}
190		}
191	}
192	
193	// TestConcurrentDistinctPaymentsExactlySettleBill 覆盖结清边界：
194	// 初始余额 1000，两笔标识不同的付款 700 与 300 并发到达，合计划好等于应付。
195	// 两笔都应首次登记成功，最终付清；不能把这种合法的分次付款当成超额拒绝。
196	// 只有实际把余额结清为 0 的那笔返回付清，另一笔返回它登记后的剩余余额。
197	func TestConcurrentDistinctPaymentsExactlySettleBill(t *testing.T) {
198		s, _ := newTestService(utc(2026, 2, 1, 0, 0))
199		mustPlan(t, s, Plan{ID: "plan1000", MonthlyFee: 1000, TaxRateBasisPoints: 0})
200	
201		const rounds = 100
202		for iter := 0; iter < rounds; iter++ {
203			acct := fmt.Sprintf("b%d", iter)
204			mustBill1000(t, s, acct)
205	
206			res := contendOnce(s, acct,
207				paymentOutcome{id: "p700", amount: 700},
208				paymentOutcome{id: "p300", amount: 300},
209			)
210	
211			byID := make(map[string]paymentOutcome, 2)
212			nSettled := 0
213			for _, oc := range res {
214				// 两笔都必须首次登记成功：恰够结清的分次付款不是超额付款。
215				if oc.err != nil || !oc.r.Registered {
216					t.Fatalf("iter %d payment %q should register: r=%+v err=%v", iter, oc.id, oc.r, oc.err)
217				}
218				byID[oc.id] = oc
219				if oc.r.Settled {
220					if oc.r.BillBalance != 0 {
221						t.Fatalf("iter %d settled payment %q has non-zero balance %d", iter, oc.id, oc.r.BillBalance)
222					}
223					nSettled++
224				}
225			}
226			// 恰好一笔（后登记、实际结清余额的那笔）返回付清。
227			if nSettled != 1 {
228				t.Fatalf("iter %d want exactly one settled result, got %d: %+v", iter, nSettled, res)
229			}
230	
231			// 先登记的一笔返回其登记后的剩余余额 = 1000 - 自身金额，且未付清；
232			// 后登记的一笔余额为 0、已付清。两种先后顺序都接受。
233			for _, oc := range res {
234				wantBalance := int64(0)
235				if !oc.r.Settled {
236					wantBalance = 1000 - oc.amount
237				}
238				if oc.r.BillBalance != wantBalance || oc.r.Settled != (wantBalance == 0) {
239					t.Fatalf("iter %d payment %q result: balance=%d settled=%v, want balance=%d",
240						iter, oc.id, oc.r.BillBalance, oc.r.Settled, wantBalance)
241				}
242			}
243	
244			// 最终账单与状态：已付 1000、余额 0、已付清；应付、税额与用量不变。
245			b, err := s.GetBill(acct, jan(2026))
246			if err != nil {
247				t.Fatalf("iter %d get bill: %v", iter, err)
248			}
249			if b.Paid != 1000 || b.Balance != 0 || !b.Settled {
250				t.Fatalf("iter %d bill: paid=%d balance=%d settled=%v, want 1000/0/true",
251					iter, b.Paid, b.Balance, b.Settled)
252			}
253			if b.TotalDue != 1000 || b.Tax != 0 || b.TotalUsage != 0 {
254				t.Fatalf("iter %d bill immutable fields changed: %+v", iter, b)
255			}
256			if bs := billSummary1000(t, s, acct); bs.Paid != 1000 || bs.Balance != 0 || !bs.Settled {
257				t.Fatalf("iter %d status summary: %+v", iter, bs)
258			}
259		}
260	}
261	
262	// TestDistinctPaymentContentionBothOrdersDeterministic 以确定的顺序锁住两种可能
263	// 的获胜结果（并发测试不保证每次都调度出两种顺序，这里把两条路径各自完整走一遍）：
264	// 失败笔不占标识，可改用剩余余额以原标识首次登记并结清；随后重报最先成功的付款
265	// 只返回其历史结果，不再次扣款。
266	func TestDistinctPaymentContentionBothOrdersDeterministic(t *testing.T) {
267		s, _ := newTestService(utc(2026, 2, 1, 0, 0))
268		mustPlan(t, s, Plan{ID: "plan1000", MonthlyFee: 1000, TaxRateBasisPoints: 0})
269	
270		// 顺序一：700 先成功（已付 700、余额 300、未付清），400 超额失败。
271		mustBill1000(t, s, "big-first")
272		r700, err := s.RecordPayment("big-first", "p700", jan(2026), 700)
273		if err != nil || !r700.Registered || r700.BillBalance != 300 || r700.Settled {
274			t.Fatalf("700 first: r=%+v err=%v", r700, err)
275		}
276		if _, err := s.RecordPayment("big-first", "p400", jan(2026), 400); !errors.Is(err, ErrPaymentExceedsBalance) {
277			t.Fatalf("400 after 700 should exceed balance: %v", err)
278		}
279		// p400 未被占用：改金额 300 首次成功并结清。
280		topUp, err := s.RecordPayment("big-first", "p400", jan(2026), 300)
281		if err != nil || !topUp.Registered || topUp.BillBalance != 0 || !topUp.Settled {
282			t.Fatalf("reuse p400 for 300: r=%+v err=%v", topUp, err)
283		}
284		// 重报 p700：返回首次登记后的历史结果（余额 300、未付清），不再次扣款。
285		replay, err := s.RecordPayment("big-first", "p700", jan(2026), 700)
286		if err != nil || replay.Registered || replay.BillBalance != 300 || replay.Settled {
287			t.Fatalf("replay p700: r=%+v err=%v, want historical 300/false", replay, err)
288		}
289		if b, _ := s.GetBill("big-first", jan(2026)); b.Paid != 1000 || b.Balance != 0 || !b.Settled {
290			t.Fatalf("big-first final bill: %+v", b)
291		}
292	
293		// 顺序二：400 先成功（已付 400、余额 600、未付清），700 超额失败。
294		mustBill1000(t, s, "small-first")
295		r400, err := s.RecordPayment("small-first", "p400", jan(2026), 400)
296		if err != nil || !r400.Registered || r400.BillBalance != 600 || r400.Settled {
297			t.Fatalf("400 first: r=%+v err=%v", r400, err)
298		}
299		if _, err := s.RecordPayment("small-first", "p700", jan(2026), 700); !errors.Is(err, ErrPaymentExceedsBalance) {
300			t.Fatalf("700 after 400 should exceed balance: %v", err)
301		}
302		// p700 未被占用：改金额 600 首次成功并结清。
303		topUp, err = s.RecordPayment("small-first", "p700", jan(2026), 600)
304		if err != nil || !topUp.Registered || topUp.BillBalance != 0 || !topUp.Settled {
305			t.Fatalf("reuse p700 for 600: r=%+v err=%v", topUp, err)
306		}
307		// 重报 p400：返回首次登记后的历史结果（余额 600、未付清），不再次扣款。
308		replay, err = s.RecordPayment("small-first", "p400", jan(2026), 400)
309		if err != nil || replay.Registered || replay.BillBalance != 600 || replay.Settled {
310			t.Fatalf("replay p400: r=%+v err=%v, want historical 600/false", replay, err)
311		}
312		if b, _ := s.GetBill("small-first", jan(2026)); b.Paid != 1000 || b.Balance != 0 || !b.Settled {
313			t.Fatalf("small-first final bill: %+v", b)
314		}
315	}
