		}

		// 结果与累计必须自洽：拒绝即 0、接收即 3，杜绝撕裂。
		if eventRejected {
			wantSettleRacyFebUsage(t, s, 0)
		} else {
			wantSettleRacyFebUsage(t, s, 3)
		}

		// 并发结束后的共同终态：账单已结清、账户不再停用、订阅条件不变、
		// 二月仍未出账。
