		wantSettleRacyState(t, s, false)
		if _, err := s.GetBill(settleRacyAcct, feb(2026)); !errors.Is(err, ErrBillNotFound) {
			t.Fatalf("iter %d feb bill must not exist: %v", iter, err)
		}

