	wantSettleRacyBill(t, s, 400, 600, false)
	wantSettleRacyFebUsage(t, s, 0)
	if _, err := s.GetBill(settleRacyAcct, feb(2026)); !errors.Is(err, ErrBillNotFound) {
		t.Fatalf("feb bill should not exist at start: %v", err)
	}
	return s, clk
